record.field:
{
    "type": "object",
    "properties": {
        "search_text": {
            "type": "string",
            "description": "Name, email, tax id or reference to look for (min. 2 characters).",
            "maxLength": 100
        },
        "role": {
            "type": "string",
            "description": "Who is being searched, only used to sort the results.",
            "enum": [
                "customer",
                "vendor"
            ],
            "maxLength": 10
        }
    },
    "required": [
        "search_text"
    ]
}

{
    "type": "object",
    "properties": {
        "search_text": {
            "type": "string",
            "description": "Name, internal reference or barcode (min. 2 characters).",
            "maxLength": 100
        },
        "purpose": {
            "type": "string",
            "description": "'sale' for quotations, 'purchase' for requests for quotation.",
            "enum": [
                "sale",
                "purchase"
            ],
            "maxLength": 10
        }
    },
    "required": [
        "search_text",
        "purpose"
    ]
}

{
    "type": "object",
    "properties": {
        "customer_id": {
            "type": "number",
            "description": "Id of the customer, obtained with 'Find Partner'."
        },
        "customer_reference": {
            "type": "string",
            "description": "Reference the customer uses for this order (optional).",
            "maxLength": 100
        },
        "note": {
            "type": "string",
            "description": "Free text printed on the quotation (optional).",
            "maxLength": 500
        },
        "validity_date": {
            "type": "string",
            "description": "Quotation expiry date, YYYY-MM-DD (optional).",
            "maxLength": 10,
            "pattern": "\\d{4}-\\d{2}-\\d{2}"
        }
    },
    "required": [
        "customer_id"
    ]
}

{
    "type": "object",
    "properties": {
        "order_id": {
            "type": "number",
            "description": "Id of the quotation."
        },
        "customer_reference": {
            "type": "string",
            "description": "New customer reference (optional).",
            "maxLength": 100
        },
        "note": {
            "type": "string",
            "description": "New note printed on the quotation (optional).",
            "maxLength": 500
        },
        "validity_date": {
            "type": "string",
            "description": "New expiry date, YYYY-MM-DD (optional).",
            "maxLength": 10,
            "pattern": "\\d{4}-\\d{2}-\\d{2}"
        }
    },
    "required": [
        "order_id"
    ]
}

{
    "type": "object",
    "properties": {
        "order_id": {
            "type": "number",
            "description": "Id of the quotation."
        },
        "product_id": {
            "type": "number",
            "description": "Id of the product, obtained with 'Find Product'."
        },
        "quantity": {
            "type": "number",
            "description": "Quantity, greater than 0."
        },
        "price_unit": {
            "type": "number",
            "description": "Unit price, only if the user asked for a specific one (optional)."
        },
        "discount_percent": {
            "type": "number",
            "description": "Discount percentage 0-100, only if the user asked for it (optional)."
        }
    },
    "required": [
        "order_id",
        "product_id",
        "quantity"
    ]
}

{
    "type": "object",
    "properties": {
        "line_id": {
            "type": "number",
            "description": "Id of the order line (line_id, not the product id)."
        },
        "quantity": {
            "type": "number",
            "description": "New quantity, greater than 0 (optional)."
        },
        "price_unit": {
            "type": "number",
            "description": "New unit price (optional)."
        },
        "discount_percent": {
            "type": "number",
            "description": "New discount percentage 0-100 (optional)."
        }
    },
    "required": [
        "line_id"
    ]
}

{
    "type": "object",
    "properties": {
        "vendor_id": {
            "type": "number",
            "description": "Id of the vendor, obtained with 'Find Partner'."
        },
        "vendor_reference": {
            "type": "string",
            "description": "Vendor reference / quotation number (optional).",
            "maxLength": 100
        },
        "note": {
            "type": "string",
            "description": "Free text for the vendor (optional).",
            "maxLength": 500
        },
        "expected_date": {
            "type": "string",
            "description": "Expected receipt date, YYYY-MM-DD (optional).",
            "maxLength": 10,
            "pattern": "\\d{4}-\\d{2}-\\d{2}"
        }
    },
    "required": [
        "vendor_id"
    ]
}

{
    "type": "object",
    "properties": {
        "order_id": {
            "type": "number",
            "description": "Id of the request for quotation."
        },
        "vendor_reference": {
            "type": "string",
            "description": "New vendor reference (optional).",
            "maxLength": 100
        },
        "note": {
            "type": "string",
            "description": "New note (optional).",
            "maxLength": 500
        },
        "expected_date": {
            "type": "string",
            "description": "New expected receipt date, YYYY-MM-DD (optional).",
            "maxLength": 10,
            "pattern": "\\d{4}-\\d{2}-\\d{2}"
        }
    },
    "required": [
        "order_id"
    ]
}

{
    "type": "object",
    "properties": {
        "order_id": {
            "type": "number",
            "description": "Id of the request for quotation."
        },
        "product_id": {
            "type": "number",
            "description": "Id of the product, obtained with 'Find Product'."
        },
        "quantity": {
            "type": "number",
            "description": "Quantity, greater than 0."
        },
        "price_unit": {
            "type": "number",
            "description": "Unit price, only if the user asked for a specific one (optional)."
        }
    },
    "required": [
        "order_id",
        "product_id",
        "quantity"
    ]
}

{
    "type": "object",
    "properties": {
        "line_id": {
            "type": "number",
            "description": "Id of the order line (line_id, not the product id)."
        },
        "quantity": {
            "type": "number",
            "description": "New quantity, greater than 0 (optional)."
        },
        "price_unit": {
            "type": "number",
            "description": "New unit price (optional)."
        }
    },
    "required": [
        "line_id"
    ]
}
